import { useState } from 'react';
import {
  JxSegmentedControl,
  JxSegmentedControlItem,
  JxSlider,
  JxSwitch,
  JxSelect,
  JxSelectOption,
  JxDivider,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'sans' | 'serif' | 'mono';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceSettingsScreenProps {
  defaultSettings?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_LABELS: Record<Font, string> = {
  system: 'Системный',
  sans: 'Без засечек',
  serif: 'С засечками',
  mono: 'Моноширинный',
};

export default function AppearanceSettingsScreen({
  defaultSettings,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>(
    defaultSettings ?? { theme: 'system', scale: 100, dense: false, font: 'system' }
  );

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  return (
    <section
      className="jx-panel"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
        padding: 'var(--jx-space-6)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h2 className="jx-heading-md">Внешний вид</h2>
        <JxBadge variant="outline">{THEME_LABELS[settings.theme]}</JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <span className="jx-label">Тема</span>
        <JxSegmentedControl
          value={settings.theme}
          onValueChange={(value) => update({ theme: value as Theme })}
        >
          <JxSegmentedControlItem value="light">Светлая</JxSegmentedControlItem>
          <JxSegmentedControlItem value="dark">Тёмная</JxSegmentedControlItem>
          <JxSegmentedControlItem value="system">Системная</JxSegmentedControlItem>
        </JxSegmentedControl>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span className="jx-label">Масштаб интерфейса</span>
          <span className="jx-text-muted">{settings.scale}%</span>
        </div>
        <JxSlider
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onValueChange={(value) => update({ scale: Array.isArray(value) ? value[0] : value })}
          aria-label="Масштаб интерфейса"
        />
      </div>

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <span className="jx-label">Плотная вёрстка</span>
          <span className="jx-text-muted">Меньше отступов между элементами</span>
        </div>
        <JxSwitch
          checked={settings.dense}
          onCheckedChange={(checked) => update({ dense: checked })}
          aria-label="Плотная вёрстка"
        />
      </div>

      <JxDivider />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
        <h3 className="jx-heading-sm">Ещё</h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
          <span className="jx-label">Шрифт</span>
          <JxSelect
            value={settings.font}
            onValueChange={(value) => update({ font: value as Font })}
          >
            {(Object.keys(FONT_LABELS) as Font[]).map((font) => (
              <JxSelectOption key={font} value={font}>
                {FONT_LABELS[font]}
              </JxSelectOption>
            ))}
          </JxSelect>
        </div>
      </div>
    </section>
  );
}

